from datetime import timedelta

import pandas as pd

import config
import database
import importers
import models
import support


PROOF_URL = 'https://sportangebot.unisg.ch/public-discovery-schedule?selectedDate=2026-11-03'
PROOF_TIME = '2026-11-02 09:00:00'
PROVENANCE_FIELDS = ('provenance_kind', 'forecast_anchor_date', 'evidence_weeks',
                     'verification_url', 'verified_at')


class EventProvenanceTests(support.DatabaseCase):
    """Use synthetic in-memory rows to retain evidence, identities and legacy functionality."""

    def setUp(self):
        """Store one ordinary event before adding any optional provenance."""
        super().setUp()
        self.save()
        self.event_id = self.scalar('SELECT id FROM events')
        self.series_id = self.scalar('SELECT series_id FROM events')
        self.start = support.NOW + timedelta(days=1)
        self.end = support.NOW + timedelta(days=4)

    def add_proof(self, event_id=None, kind='website'):
        """Attach either website evidence or an explicitly provisional observation pattern."""
        event_id = self.event_id if event_id is None else event_id
        values = (event_id, kind, '2026-10-30', 3, PROOF_TIME,
                  PROOF_URL if kind == 'website' else None,
                  PROOF_TIME if kind == 'website' else None)
        with self.connection:
            self.connection.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,
                 verification_url,verified_at) VALUES (?,?,?,?,?,?,?)''', values)

    def add_archive(self):
        """Retain a private source observation whose aggregate counts are not user ratings."""
        with self.connection:
            self.connection.execute('''INSERT INTO training_imports
                (id,file_name,source_fingerprint,imported_at)
                VALUES (8,'private-source.csv','private-fixture-hash',?)''', (PROOF_TIME,))
            self.connection.execute('''INSERT INTO training_history
                (id,import_id,source_row,sport,weekday_text,start_time,date_original,training_date,
                 participants_signed_up,participants_teacher,max_participants)
                VALUES (61,8,2,'Yoga','Friday','08:00','Freitag, 30. Oktober 2026',
                        '2026-10-30',0,3,9999)''')

    def catalogue_snapshot(self):
        """Capture complete catalogue and archive values using fixed, readable SQL statements."""
        statements = ('SELECT * FROM directions ORDER BY id',
                      'SELECT * FROM bundles ORDER BY id', 'SELECT * FROM clubs ORDER BY id',
                      'SELECT * FROM series ORDER BY id', 'SELECT * FROM events ORDER BY id',
                      'SELECT * FROM event_provenance ORDER BY event_id',
                      'SELECT * FROM training_imports ORDER BY id',
                      'SELECT * FROM training_history ORDER BY id')
        result = []
        for statement in statements:
            result.append([tuple(row) for row in self.connection.execute(statement)])
        return result

    def test_unproven_legacy_event_remains_unspecified(self):
        """Missing provenance does not turn an imported or demonstration row into website proof."""
        row = database.get_event_row(self.connection, self.event_id)
        self.assertEqual(set(row), set(config.EVENT_RECORD_FIELDS))
        for field in PROVENANCE_FIELDS:
            self.assertIsNone(row[field])
        legacy = row.copy()
        for field in PROVENANCE_FIELDS:
            legacy.pop(field)
        event = models.event_from_row(legacy)
        for field in PROVENANCE_FIELDS:
            self.assertIsNone(getattr(event, field))

    def test_website_and_projected_rows_reach_range_and_single_queries(self):
        """Both joined query paths preserve nullable values and their distinct evidence states."""
        self.add_proof()
        row = support.record(external_id='second-course', title='Yoga', club_name='')
        self.save([row])
        second = self.scalar('SELECT MAX(id) FROM events')
        self.add_proof(second, 'projected')
        records = database.get_event_records(self.connection, support.NOW, self.end)
        by_id = {record['id']: record for record in records}
        self.assertEqual(by_id[self.event_id]['provenance_kind'], 'website')
        self.assertEqual(by_id[self.event_id]['verification_url'], PROOF_URL)
        self.assertEqual(by_id[second]['provenance_kind'], 'projected')
        self.assertIsNone(by_id[second]['verification_url'])
        self.assertEqual(by_id[second]['evidence_weeks'], 3)
        self.assertIs(type(by_id[second]['evidence_weeks']), int)
        self.assertEqual(database.get_event_row(self.connection, second), by_id[second])
        frame = database.get_events_df(self.connection, support.NOW, self.end)
        self.assertEqual(frame.loc[second, 'provenance_kind'], 'projected')
        self.assertNotIn('participants_signed_up', frame.columns)
        self.assertNotIn('file_name', frame.columns)

    def test_complete_projected_and_website_metadata_construct_domain_events(self):
        """Published and projected states remain separate from event availability."""
        projected = support.event(provenance_kind='projected',
                                  forecast_anchor_date='2026-10-30', evidence_weeks=3,
                                  status='unknown')
        self.assertEqual(projected.provenance_kind, 'projected')
        self.assertEqual(projected.evidence_weeks, 3)
        self.assertEqual(projected.status, 'unknown')
        website = support.event(provenance_kind='website', verification_url=PROOF_URL,
                                verified_at=PROOF_TIME, status='unknown')
        self.assertEqual(website.provenance_kind, 'website')
        self.assertIsNone(website.forecast_anchor_date)
        self.assertEqual(website.status, 'unknown')

    def test_rejects_incomplete_or_inconsistent_provenance(self):
        """A state label alone cannot claim evidence and unspecified rows cannot carry proof."""
        invalid = ({'provenance_kind': 'projected'},
                   {'provenance_kind': 'website'},
                   {'provenance_kind': 'verified'},
                   {'verification_url': PROOF_URL},
                   {'verified_at': PROOF_TIME},
                   {'forecast_anchor_date': '2026-10-30', 'evidence_weeks': 3},
                   {'provenance_kind': 'projected', 'forecast_anchor_date': '2026-10-30',
                    'evidence_weeks': 3, 'verification_url': PROOF_URL})
        for values in invalid:
            with self.subTest(values=values), self.assertRaises(ValueError):
                support.event(**values)

    def test_rejects_invalid_anchor_and_noninteger_evidence(self):
        """Projected evidence requires a canonical date and three or four distinct weeks."""
        for anchor in ('2026-1-6', '2026-02-30', 'not-a-date'):
            with self.subTest(anchor=anchor), self.assertRaises(ValueError):
                support.event(provenance_kind='projected', forecast_anchor_date=anchor,
                              evidence_weeks=3)
        for weeks in (None, True, 2, 5, 3.5, '3'):
            with self.subTest(weeks=weeks), self.assertRaises(ValueError):
                support.event(provenance_kind='projected', forecast_anchor_date='2026-10-30',
                              evidence_weeks=weeks)

    def test_rejects_unsafe_or_undated_website_evidence(self):
        """Website proof needs a real HTTPS URL and a canonical saved check timestamp."""
        for url in ('http://example.test/proof', 'javascript:alert(1)', 'https://', ''):
            with self.subTest(url=url), self.assertRaises(ValueError):
                support.event(provenance_kind='website', verification_url=url,
                              verified_at=PROOF_TIME)
        for stamp in ('2026-11-02', '2026-02-30 09:00:00', '2026-11-02T09:00:00Z', ''):
            with self.subTest(stamp=stamp), self.assertRaises(ValueError):
                support.event(provenance_kind='website', verification_url=PROOF_URL,
                              verified_at=stamp)

    def test_dataframe_nulls_do_not_become_false_provenance(self):
        """Nullable pandas values normalize to unspecified rather than strings or false proof."""
        row = database.get_event_row(self.connection, self.event_id)
        for field in PROVENANCE_FIELDS:
            row[field] = pd.NA if field == 'evidence_weeks' else float('nan')
        event = models.event_from_row(row)
        for field in PROVENANCE_FIELDS:
            self.assertIsNone(getattr(event, field))

    def test_dataframe_integer_coercion_is_exact_without_truncation(self):
        """SQL's nullable numeric columns can carry integral floats but never fractional weeks."""
        self.add_proof(kind='projected')
        row = database.get_event_row(self.connection, self.event_id)
        row['evidence_weeks'] = 3.0
        event = models.event_from_row(row)
        self.assertEqual(event.evidence_weeks, 3)
        self.assertIs(type(event.evidence_weeks), int)
        row['evidence_weeks'] = 3.5
        with self.assertRaises(ValueError):
            models.event_from_row(row)

    def test_confirmed_and_training_queries_retain_the_same_proof(self):
        """Personal confirmations and attended-rating joins carry the shared source metadata."""
        user = database.create_user(self.connection, 'Alex', now=support.NOW)
        database.set_setting(self.connection, 'current_user_id', user)
        self.add_proof()
        database.save_interaction(self.connection, user, self.event_id, 'confirm', now=support.NOW)
        confirmed = database.get_calendar_confirmations(self.connection, support.NOW, self.end)
        self.assertEqual(confirmed.loc[self.event_id, 'provenance_kind'], 'website')
        later = support.NOW + timedelta(days=5)
        database.save_interaction(self.connection, user, self.event_id, 'attended', now=later)
        database.save_interaction(self.connection, user, self.event_id, 'rate', rating=4, now=later)
        training = database.get_training_interactions_df(self.connection, later)
        self.assertEqual(len(training), 1)
        row = training.reset_index().to_dict('records')[0]
        self.assertEqual(row['provenance_kind'], 'website')
        self.assertEqual(row['verification_url'], PROOF_URL)
        row['id'] = row['event_id']
        self.assertEqual(models.event_from_row(row).provenance_kind, 'website')

    def test_generic_import_preserves_curated_course_and_event_fields(self):
        """Refresh cannot attach old website proof to rewritten titles, durations or statuses."""
        self.add_proof()
        before = self.catalogue_snapshot()
        replacement = support.record(title='Changed by generic input', location='Zurich',
                                     end=self.start + timedelta(hours=8), status='closed')
        self.save([replacement])
        self.assertEqual(self.catalogue_snapshot(), before)

    def test_generic_import_still_updates_an_unproven_event(self):
        """Protecting curated rows does not freeze the ordinary demo/import path."""
        self.save([support.record(title='Updated ordinary title', status='apply')])
        row = database.get_event_row(self.connection, self.event_id)
        self.assertEqual(row['title'], 'Updated ordinary title')
        self.assertEqual(row['status'], 'apply')
        self.assertIsNone(row['provenance_kind'])

    def test_reconciliation_keeps_projected_and_website_events(self):
        """A different source batch cannot delete curated dates that it does not own."""
        self.add_proof()
        self.save([support.record(external_id='projected-course', title='Yoga')])
        projected = self.scalar('SELECT MAX(id) FROM events')
        self.add_proof(projected, 'projected')
        self.save([support.record(external_id='unproven-absent', title='Old generic event')])
        unproven = self.scalar('SELECT MAX(id) FROM events')
        self.save([support.record(external_id='retained-batch', title='Current generic event')],
                  reconcile=True)
        self.assertIsNotNone(database.get_event_row(self.connection, self.event_id))
        self.assertIsNotNone(database.get_event_row(self.connection, projected))
        self.assertIsNone(database.get_event_row(self.connection, unproven))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 2)

    def test_past_cleanup_cascades_proof_but_retains_private_archive(self):
        """Removing an unplanned old occurrence does not remove its historical source archive."""
        self.add_proof()
        self.add_archive()
        archive = [tuple(row) for row in self.connection.execute('SELECT * FROM training_history')]
        removed = database.delete_past_unconfirmed_events(self.connection, self.end)
        self.assertEqual(removed, 1)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 1)
        self.assertEqual([tuple(row) for row in
                          self.connection.execute('SELECT * FROM training_history')], archive)
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_past_cleanup_retains_referenced_website_event(self):
        """A user's retained plan keeps its occurrence and proof available for feedback."""
        self.add_proof()
        user = database.create_user(self.connection, 'Alex', now=support.NOW)
        database.save_interaction(self.connection, user, self.event_id, 'confirm', now=support.NOW)
        self.assertEqual(database.delete_past_unconfirmed_events(self.connection, self.end), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 1)

    def test_catalogue_identity_is_explicit_and_defaults_to_demo(self):
        """An ordinary database stays in demo mode until its reviewed identity is recorded."""
        self.assertFalse(database.is_reviewed_catalogue(self.connection))
        self.assertEqual(database.get_catalogue_id(self.connection), 'demo')
        database.set_setting(self.connection, 'catalogue_mode', 'reviewed_unisport')
        database.set_setting(self.connection, 'catalogue_id', 'fixture-reviewed-1')
        self.assertTrue(database.is_reviewed_catalogue(self.connection))
        self.assertEqual(database.get_catalogue_id(self.connection), 'fixture-reviewed-1')

    def test_reviewed_reset_removes_profile_but_retains_catalogue_and_archive(self):
        """Reset in reviewed mode clears user state while keeping all approved activity data."""
        self.add_proof()
        self.add_archive()
        user = database.complete_onboarding(self.connection, 'Alex', ['career'], 'demo',
                                            now=support.NOW)
        friend = database.create_user(self.connection, 'Robin', now=support.NOW)
        database.save_interaction(self.connection, user, self.event_id, 'confirm', now=support.NOW)
        with self.connection:
            self.connection.execute('''INSERT INTO favorites (user_id,kind,target_id,created_at)
                VALUES (?,'series',?,?)''', (user, self.series_id, PROOF_TIME))
            self.connection.execute('''INSERT INTO friendships (user_id,friend_id,created_at)
                VALUES (?,?,?)''', (user, friend, PROOF_TIME))
            self.connection.execute('''INSERT INTO invitations
                (sender_id,recipient_id,event_id,created_at) VALUES (?,?,?,?)''',
                (user, friend, self.event_id, PROOF_TIME))
        settings = {'catalogue_mode': 'reviewed_unisport', 'catalogue_id': 'fixture-reviewed-1',
                    'setup_done': '1', 'unrelated_catalogue_note': 'retained'}
        for key, value in settings.items():
            database.set_setting(self.connection, key, value)
        before = self.catalogue_snapshot()
        database.reset_database(self.connection)
        self.assertEqual(self.catalogue_snapshot(), before)
        for query in ('SELECT COUNT(*) FROM users', 'SELECT COUNT(*) FROM user_directions',
                      'SELECT COUNT(*) FROM interactions', 'SELECT COUNT(*) FROM invitations',
                      'SELECT COUNT(*) FROM friendships', 'SELECT COUNT(*) FROM favorites'):
            self.assertEqual(self.scalar(query), 0)
        for key, value in settings.items():
            self.assertEqual(database.get_setting(self.connection, key), value)
        self.assertIsNone(database.get_setting(self.connection, 'current_user_id'))
        self.assertIsNone(database.get_setting(self.connection, 'onboarding_done'))
        self.assertIsNotNone(database.get_setting(self.connection, 'taxonomy_version'))
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_legacy_reset_still_rebuilds_empty_catalogue_and_retains_archive(self):
        """The ordinary demo reset keeps its established semantics and private archives."""
        self.add_proof()
        self.add_archive()
        database.reset_database(self.connection)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM event_provenance'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM directions'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 1)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 1)
